-- Espelho local (SQLite) de supabase/migrations/20261112175107_intelligence_motion_capture.sql, usado pelos testes locais.
-- SQLite nao altera CHECK: capture_consents e capture_items sao recriadas com as regras novas e os dados copiados.
-- SQLite nao tem expressao regular em CHECK: os formatos de camera_id e sha256 usam GLOB com o mesmo efeito.
CREATE TABLE `capture_consents_new` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `email` text NOT NULL, `mode` text NOT NULL CHECK (`mode` IN ('lesson','interview','voice','motion')), `policy_version` text NOT NULL, `camera` integer NOT NULL DEFAULT 0, `photos` integer NOT NULL DEFAULT 0, `recording` integer NOT NULL DEFAULT 0, `accepted_at` integer NOT NULL, `revoked_at` integer, `voice` integer NOT NULL DEFAULT 0, `motion` integer NOT NULL DEFAULT 0, CHECK ((`mode`='voice' AND `voice`=1 AND `camera`=0 AND `photos`=0 AND `recording`=0) OR (`mode`<>'voice' AND `voice`=0)), CHECK ((`mode`='motion' AND `motion`=1 AND `camera`=1 AND `voice`=0) OR (`mode`<>'motion' AND `motion`=0)));
INSERT INTO `capture_consents_new` (`id`,`user_id`,`email`,`mode`,`policy_version`,`camera`,`photos`,`recording`,`accepted_at`,`revoked_at`,`voice`) SELECT `id`,`user_id`,`email`,`mode`,`policy_version`,`camera`,`photos`,`recording`,`accepted_at`,`revoked_at`,`voice` FROM `capture_consents`;
CREATE TABLE `capture_sessions` (`id` text PRIMARY KEY NOT NULL, `consent_id` text NOT NULL, `stage` text NOT NULL CHECK (`stage` IN ('face','body','lesson')), `script_version` text NOT NULL, `started_at` integer NOT NULL, `ended_at` integer, FOREIGN KEY (`consent_id`) REFERENCES `capture_consents`(`id`), CHECK (`ended_at` IS NULL OR `ended_at` >= `started_at`));
CREATE TABLE `capture_cameras` (`session_id` text NOT NULL, `camera_id` text NOT NULL CHECK (length(`camera_id`) BETWEEN 1 AND 16 AND `camera_id` NOT GLOB '*[^a-z0-9_]*'), `role` text NOT NULL CHECK (`role` IN ('close','medium','wide','reference')), `source` text NOT NULL CHECK (`source` IN ('browser','device_file')), `device_label` text, `location` text CHECK (`location` IN ('owner_disk','owner_drive')), `file_name` text, `sha256` text CHECK (length(`sha256`)=64 AND `sha256` NOT GLOB '*[^0-9a-f]*'), `bytes` integer CHECK (`bytes` > 0), `duration_ms` integer CHECK (`duration_ms` BETWEEN 1000 AND 14400000), `width` integer CHECK (`width` BETWEEN 320 AND 7680), `height` integer CHECK (`height` BETWEEN 240 AND 7680), `fps` real CHECK (`fps` BETWEEN 10 AND 240), `codec` text, `sync_offset_ms` integer, `drift_ppm` real, `created_at` integer NOT NULL, PRIMARY KEY (`session_id`,`camera_id`), FOREIGN KEY (`session_id`) REFERENCES `capture_sessions`(`id`), CHECK ((`source`='browser' AND `location` IS NULL AND `file_name` IS NULL AND `sha256` IS NULL AND `bytes` IS NULL) OR (`source`='device_file' AND `location` IS NOT NULL AND `file_name` IS NOT NULL AND `sha256` IS NOT NULL AND `bytes` IS NOT NULL)));
CREATE TABLE `capture_items_new` (`id` text PRIMARY KEY NOT NULL, `consent_id` text NOT NULL, `session_id` text NOT NULL, `kind` text NOT NULL CHECK (`kind` IN ('photo','recording','voice','track')), `moment` text NOT NULL CHECK (`moment` IN ('answer_start','expression','interval','session','script_line','room_tone','track_chunk')), `key` text NOT NULL UNIQUE, `mime` text NOT NULL, `size` integer NOT NULL CHECK (`size` > 0), `created_at` integer NOT NULL, `script_version` text, `line_id` text, `duration_ms` integer, `sample_rate` integer, `camera_id` text, `track` text, `t0_ms` integer, FOREIGN KEY (`consent_id`) REFERENCES `capture_consents`(`id`), FOREIGN KEY (`session_id`,`camera_id`) REFERENCES `capture_cameras`(`session_id`,`camera_id`), CHECK ((`kind`='voice' AND `mime`='audio/wav' AND `script_version` IS NOT NULL AND `duration_ms` BETWEEN 300 AND 40000 AND `sample_rate` BETWEEN 16000 AND 96000 AND ((`moment`='script_line' AND `line_id` IS NOT NULL) OR (`moment`='room_tone' AND `line_id` IS NULL)) AND `camera_id` IS NULL AND `track` IS NULL AND `t0_ms` IS NULL) OR (`kind`='track' AND `mime`='application/gzip' AND `moment`='track_chunk' AND `camera_id` IS NOT NULL AND `track` IN ('face','pose','hands','marks') AND `t0_ms` >= 0 AND `duration_ms` BETWEEN 1 AND 120000 AND `script_version` IS NULL AND `line_id` IS NULL AND `sample_rate` IS NULL) OR (`kind` IN ('photo','recording') AND `moment` NOT IN ('script_line','room_tone','track_chunk') AND `script_version` IS NULL AND `line_id` IS NULL AND `duration_ms` IS NULL AND `sample_rate` IS NULL AND `track` IS NULL AND `t0_ms` IS NULL)));
INSERT INTO `capture_items_new` (`id`,`consent_id`,`session_id`,`kind`,`moment`,`key`,`mime`,`size`,`created_at`,`script_version`,`line_id`,`duration_ms`,`sample_rate`) SELECT `id`,`consent_id`,`session_id`,`kind`,`moment`,`key`,`mime`,`size`,`created_at`,`script_version`,`line_id`,`duration_ms`,`sample_rate` FROM `capture_items`;
CREATE TABLE `style_profiles` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `consent_id` text NOT NULL, `schema_version` text NOT NULL, `profile_version` text NOT NULL, `key` text NOT NULL UNIQUE, `size` integer NOT NULL CHECK (`size` > 0), `created_at` integer NOT NULL, `approved_at` integer, `revoked_at` integer, UNIQUE (`user_id`,`profile_version`), FOREIGN KEY (`consent_id`) REFERENCES `capture_consents`(`id`));
DROP TABLE `capture_items`;
DROP TABLE `capture_consents`;
ALTER TABLE `capture_consents_new` RENAME TO `capture_consents`;
ALTER TABLE `capture_items_new` RENAME TO `capture_items`;
CREATE INDEX `capture_consents_user` ON `capture_consents` (`user_id`,`accepted_at`);
CREATE INDEX `capture_items_session` ON `capture_items` (`session_id`,`created_at`);
CREATE INDEX `capture_items_voice_line_idx` ON `capture_items` (`consent_id`,`script_version`,`line_id`,`created_at`) WHERE `kind`='voice';
CREATE INDEX `capture_items_track_idx` ON `capture_items` (`session_id`,`camera_id`,`track`,`t0_ms`,`created_at`) WHERE `kind`='track';
CREATE INDEX `capture_sessions_consent` ON `capture_sessions` (`consent_id`,`started_at`);
